import {state,DEMO} from '../../core/state.js?v=f62135f1ecf7';
import {api} from '../../core/api.js?v=f62135f1ecf7';
import {refresh} from '../../core/events.js?v=f62135f1ecf7';
import {T,esc,icon,heading,btn,panel,field,select,formEnd,toast,nativeRequired,modal} from '../../core/ui.js?v=f62135f1ecf7';
let profile={};
export async function load(){profile=await api('studio/profile');}
export function render(){return heading(T('Tài khoản & thiết lập cá nhân','Account & preferences'),T('Quản lý hồ sơ, khóa YouTube và bảo mật tài khoản.','Manage your profile, YouTube key and account security.'))+`<div class="split-grid"><div class="stack">${panel(T('Hồ sơ','Profile'),`<form data-submit="account:profile">${field('name',T('Tên hiển thị','Display name'),profile.name,'text','maxlength="150"')}${field('username',T('Tên đăng nhập','Username'),profile.username,'text','readonly')}${field('email','Email',profile.email||'','email','readonly')}${select('language',T('Ngôn ngữ giao diện','Interface language'),[['vi','Tiếng Việt'],['en','English']],state.language)}${formEnd()}</form><div class="setting-row"><div class="setting-copy"><h3>${profile.email_verified?T('Email đã xác minh','Email verified'):T('Email chưa xác minh','Email not verified')}</h3><p>${T('Xác minh trước khi nhận lời mời nếu máy chủ yêu cầu.','Verify before accepting invitations when required by the server.')}</p></div>${btn(T('Gửi xác minh','Send verification'),'account:verify','','globe')}</div>`)}${panel(T('YouTube API cá nhân','Personal YouTube API'),`<form data-submit="account:youtube">${field('youtube_key',T('API key · để trống để giữ nguyên','API key · leave blank to keep the current key'),'','password',`autocomplete="new-password" ${DEMO?'disabled':''}`)}<label class="check-row"><input name="clear_youtube_key" type="checkbox">${T('Xóa khóa cá nhân','Remove personal key')}</label><p class="form-hint">${profile.youtube_configured?T('Đã có khóa cá nhân hoặc khóa mặc định máy chủ.','A personal or server-default key is configured.'):T('Chưa có khóa YouTube.','No YouTube key configured.')}</p>${formEnd()}</form>`)}</div><div class="stack">${DEMO?panel(T('Đổi vai trò demo','Switch demo user'),`<div class="demo-roles">${state.workspace.members.map(m=>`<button class="demo-role ${m.id===state.workspace.user.id?'active':''}" data-action="account:switch" data-id="${m.id}"><span class="avatar">${esc(m.username.toUpperCase())}</span><span><b>${esc(m.name)}</b><small>${m.role==='manager'?T('Quản lý dự án','Project manager'):T('Gán nhãn và kiểm tra','Annotator and reviewer')}</small></span>${m.id===state.workspace.user.id?icon('check',17):icon('chevron',17)}</button>`).join('')}</div>`,T('Tài khoản minh họa, không phải đăng nhập thật.','Synthetic identities, not real authentication.')):panel(T('Đổi mật khẩu','Change password'),`<form data-submit="account:password">${field('current_password',T('Mật khẩu hiện tại','Current password'),'','password','required autocomplete="current-password"')}${field('new_password',T('Mật khẩu mới','New password'),'','password','required autocomplete="new-password" minlength="8"')}${formEnd(T('Đổi mật khẩu','Change password'))}</form>`)}${panel(T('Chạy và quản lý source','Run and manage the source'),`<div class="guide-step"><span>1</span><div><b>${T('Windows không cần Docker','Native Windows without Docker')}</b><div class="code-block">RUN_NATIVE_WINDOWS.bat</div><small>${T('Python 3.12 + PostgreSQL 15; tác vụ nền bằng threads.','Python 3.12 + PostgreSQL 15; background tasks use threads.')}</small></div></div><div class="guide-step"><span>2</span><div><b>Docker Compose</b><div class="code-block">START_WINDOWS.bat</div><small>PostgreSQL 15 · Redis · Celery</small></div></div><p class="form-hint">${T('Xem QUICKSTART_VI.md và docs/ARCHITECTURE.md.','See QUICKSTART_VI.md and docs/ARCHITECTURE.md.')}</p>`)}</div></div>`;}
export async function action(name,el){if(name==='switch'){await api('demo/switch-user',{id:Number(el.dataset.id)});await refresh();toast(T('Đã đổi tài khoản minh họa.','Demo identity switched.'));}if(name==='verify'){if(DEMO){nativeRequired();return;}const r=await api('studio/verify/send',{});modal(T('Xác minh email','Email verification'),`<p class="subtitle">${T('Đã gửi yêu cầu qua backend email cấu hình. Với email file ở local, xem private_data/emails.','A message was sent through the configured email backend. For local file mode, open private_data/emails.')}</p>${r.preview_url?`<a class="btn primary mt24" href="${esc(r.preview_url)}">${T('Mở liên kết phát triển local','Open local development link')}</a>`:''}`);}}
export async function submit(name,f){const v=Object.fromEntries(new FormData(f));if(DEMO&&name!=='profile'){nativeRequired();return;}const payload=name==='profile'?{name:v.name,language:v.language}:name==='youtube'?{youtube_key:v.youtube_key,clear_youtube_key:f.clear_youtube_key.checked}:{current_password:v.current_password,new_password:v.new_password};await api('studio/profile/save',payload);if(v.language){state.language=v.language;localStorage.setItem('annotaflow.language',v.language);}await refresh();toast(T('Đã lưu thiết lập tài khoản.','Account settings saved.'));}
